            aIngress ^= (RotL64(aCrystalLaneB[((aIndex + 13017U)) & S_BLOCK1], 5U) ^ RotL64(aKineticLaneD[((S_BLOCK1 - aIndex + 11850U)) & S_BLOCK1], 57U));
