            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterG, 13U));
            aIngress = aIngress + RotL64(aOrbiterF, 29U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 3U) + RotL64(aOrbiterJ, 23U)) + aOrbiterG);
            aWandererA = aWandererA + (((RotL64(aIngress, 60U) + RotL64(aOrbiterC, 52U)) + aOrbiterG) + aWUSaltB[(((511U - aIndex) + 58U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aCross, 35U) + aOrbiterI) + RotL64(aOrbiterA, 13U));
            aWandererD = aWandererD + (((RotL64(aScatter, 53U) + RotL64(aOrbiterF, 3U)) + aOrbiterJ) + aWUSaltA[((aIndex + 85U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aCross, 47U) + aOrbiterE) + RotL64(aOrbiterG, 19U)) + aWUSaltC[((aIndex + 157U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aPrevious, 23U) + aOrbiterC) + RotL64(aOrbiterK, 43U)) + RotL64(aCarry, 5U));
            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 27U) + aOrbiterC) + RotL64(aOrbiterI, 37U)) + aWUSaltG[(((511U - aIndex) + 175U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aScatter, 19U) + aOrbiterC) + RotL64(aOrbiterJ, 47U)) + RotL64(aCarry, 19U));
