            aCross = RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 31631U)) & S_BLOCK1], 52U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 29359U)) & S_BLOCK1], 35U);
