            aOrbiterE = (aWandererG + RotL64(aCross, 13U)) + 0xED60701FC103CB46ULL;
            aOrbiterB = (((aWandererK + RotL64(aIngress, 18U)) + RotL64(aCarry, 5U)) + 0xBC7454F08CCF486AULL) + aOASaltF[(((511U - aIndex) + 402U)) & S_SALT1];
            aOrbiterD = ((aWandererH + RotL64(aPrevious, 57U)) + 0xEE456A688D93C056ULL) + aOASaltE[(((511U - aIndex) + 205U)) & S_SALT1];
            aOrbiterJ = ((aWandererD + RotL64(aScatter, 39U)) + 0x86044D7EF40CF675ULL) + aOASaltD[((aIndex + 74U)) & S_SALT1];
            aOrbiterK = (((aWandererC + RotL64(aCross, 47U)) + RotL64(aCarry, 39U)) + 0x2DA68C25C2F7ABBCULL) + aOASaltA[((aIndex + 254U)) & S_SALT1];
            aOrbiterH = (((aWandererA + RotL64(aScatter, 35U)) + RotL64(aCarry, 23U)) + 0xE822815397D74238ULL) + aOASaltG[((aIndex + 465U)) & S_SALT1];
            aOrbiterG = (aWandererE + RotL64(aPrevious, 43U)) + 0x0B4E3E8878312C39ULL;
            aOrbiterC = (aWandererF + RotL64(aIngress, 51U)) + 0x22421FD3EF5CA0B2ULL;
            aOrbiterF = (aWandererB + RotL64(aPrevious, 22U)) + 0xA2269F940B02BD99ULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x2A0B5708D98FE925ULL) + aOUSaltF[((aIndex + 243U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0xBDCDE5A38BB9B46CULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF1B0F58414501AD1ULL), 27U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x57B1F46624AEDC98ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x10590AAB98B70C5DULL;
            aOrbiterE = RotL64((aOrbiterE * 0xA9FBFB48D064E2A7ULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x8675D8FEA7B163F3ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xC9727EC763138A3CULL;
            aOrbiterC = RotL64((aOrbiterC * 0x8C35485881934F31ULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xEC976DAAF4F39658ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0x3CF9077E75A13D63ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6407B7F2A39842A1ULL), 3U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0xA6BE81979F0DD245ULL) + aOUSaltG[(((511U - aIndex) + 91U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x8D43F3334D0B5B0CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x888F3308BC324CD5ULL), 53U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterD) + 0xF0AE4158274B87CCULL) + aOUSaltA[(((511U - aIndex) + 397U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x74491FACBF6373D8ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x451E5F4301F5280DULL), 35U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x7C729B4BBCF55927ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x847394496B56659FULL;
