            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x2108925725E9ABE2ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0x6932C27E837BC1DBULL;
            aOrbiterK = RotL64((aOrbiterK * 0x6570C6834B2121AFULL), 23U);
