            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x754EDDCC64D1A5AEULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0x3D8457AA4918F75CULL) ^ aOUSaltH[((aIndex + 227U)) & S_SALT1];
