            aWandererF = aWandererF + ((((RotL64(aCross, 60U) + aOrbiterE) + RotL64(aOrbiterF, 47U)) + RotL64(aCarry, 37U)) + aWUSaltC[((aIndex + 54U)) & S_SALT1]);
