            //
            aOrbiterE = ((aWandererG + RotL64(aPrevious, 13U)) + 0x6D6A6E986D548487ULL) + aOASaltH[((aIndex + 425U)) & S_SALT1];
            aOrbiterA = (((aWandererJ + RotL64(aScatter, 19U)) + RotL64(aCarry, 57U)) + 0x68461498C61D3A21ULL) + aOASaltE[((aIndex + 390U)) & S_SALT1];
            aOrbiterK = (((aWandererF + RotL64(aIngress, 43U)) + RotL64(aCarry, 5U)) + 0xAE8F60FEB0ED0523ULL) + aOASaltB[(((511U - aIndex) + 196U)) & S_SALT1];
            aOrbiterJ = (aWandererI + RotL64(aCross, 29U)) + 0xCBDA9D868F650C8FULL;
            aOrbiterG = (aWandererB + RotL64(aScatter, 35U)) + 0x5530CC99491DD946ULL;
            aOrbiterF = (((aWandererE + RotL64(aCross, 57U)) + RotL64(aCarry, 23U)) + 0x59AF60C0BB63EB56ULL) + aOASaltF[(((511U - aIndex) + 469U)) & S_SALT1];
            aOrbiterH = ((aWandererC + RotL64(aIngress, 50U)) + 0x7D169355A20CE954ULL) + aOASaltD[(((511U - aIndex) + 21U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0xEEE8365252C7A8B4ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xCCE4F72B42B2D5EFULL;
            aOrbiterK = RotL64((aOrbiterK * 0x096F22DFA411566DULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x34313E33B5873A82ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0x3C1835C9D382660AULL) ^ aOUSaltE[(((511U - aIndex) + 372U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x43E3E5B325E359DBULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0xBA9284B09317F2C1ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x71204CAC572AA974ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x062CBF6E0C1C1A9DULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x67EF844D1A3E8575ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterJ) ^ 0xC44B09CFA347964AULL) ^ aOUSaltF[(((511U - aIndex) + 13U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x078D694CB87A5423ULL), 23U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x50207C49825AC14FULL) + aOUSaltC[(((511U - aIndex) + 44U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0x821F58180A8FBA5EULL) ^ aOUSaltD[((aIndex + 405U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xE2BECE51698F2DEFULL), 43U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterG) + 0xE3815D61B3192ABEULL) + aOUSaltH[(((511U - aIndex) + 111U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xD83ABB462B9C53C9ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x8E72589C4D4C5567ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xCA3289DAB1C85351ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x785F1B60C990D146ULL) ^ aOUSaltB[((aIndex + 250U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x296ED9116C2D79F1ULL), 11U);
            //
            aIngress = aOrbiterF ^ RotL64(aOrbiterA, 5U);
