            aCross = (RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 341U)) & S_BLOCK1], 37U) ^ RotL64(aSoilLaneA[((S_BLOCK1 - aIndex + 3089U)) & S_BLOCK1], 10U));
            aCross ^= (RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 3116U)) & S_BLOCK1], 21U) ^ RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 3402U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aIngress, 40U) + RotL64(aCross, 57U)) ^ (RotL64(aPrevious, 21U) ^ RotL64(aCarry, 5U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterI = ((aWandererB + RotL64(aIngress, 51U)) + 0x992627DD02FC19D7ULL) + aOASaltH[((aIndex + 258U)) & S_SALT1];
