            aOrbiterI = (((aWandererJ + RotL64(aIngress, 41U)) + RotL64(aCarry, 19U)) + 0x03E16CA42D354D37ULL) + aOASaltA[(((511U - aIndex) + 231U)) & S_SALT1];
            aOrbiterG = (((aWandererA + RotL64(aPrevious, 47U)) + RotL64(aCarry, 37U)) + 0x6E8628575B46E873ULL) + aOASaltH[((aIndex + 500U)) & S_SALT1];
