            //
            aOrbiterE = (((aWandererI + RotL64(aPrevious, 35U)) + RotL64(aCarry, 27U)) + 0x9C99DD97440F4678ULL) + aOASaltH[(((511U - aIndex) + 248U)) & S_SALT1];
