            aOrbiterD = ((aWandererE + RotL64(aIngress, 43U)) + RotL64(aCarry, 53U)) + 0xD29871559485A174ULL;
            aOrbiterB = ((aWandererC + RotL64(aCross, 10U)) + 0x9F61067D0D1EBECDULL) + aOASaltD[(((511U - aIndex) + 69U)) & S_SALT1];
            aOrbiterC = (aWandererG + RotL64(aPrevious, 3U)) + 0x6CE59420AE41610EULL;
            aOrbiterG = (((aWandererH + RotL64(aCross, 53U)) + RotL64(aCarry, 41U)) + 0xAB9338B4419A0281ULL) + aOASaltE[(((511U - aIndex) + 25U)) & S_SALT1];
