            aCross ^= (RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 16281U)) & S_BLOCK1], 27U) ^ RotL64(aCrystalLaneA[((S_BLOCK1 - aIndex + 14171U)) & S_BLOCK1], 19U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 5U) ^ RotL64(aCross, 19U)) ^ (RotL64(aCarry, 57U) + RotL64(aPrevious, 38U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = (aWandererD + RotL64(aIngress, 35U)) + 0x0B2B607F3AEE52B2ULL;
            aOrbiterG = ((aWandererJ + RotL64(aCross, 53U)) + RotL64(aCarry, 19U)) + 0xF4F246E42D586089ULL;
            aOrbiterE = (aWandererG + RotL64(aPrevious, 13U)) + 0xCE6F19DF4132DE31ULL;
            aOrbiterI = ((aWandererF + RotL64(aScatter, 47U)) + 0x88657C64CEAF1B6EULL) + aOASaltA[((aIndex + 391U)) & S_SALT1];
            aOrbiterD = (((aWandererB + RotL64(aIngress, 60U)) + RotL64(aCarry, 37U)) + 0x9E6AB73EDEB07DCCULL) + aOASaltG[((aIndex + 71U)) & S_SALT1];
            aOrbiterA = (((aWandererC + RotL64(aScatter, 21U)) + RotL64(aCarry, 3U)) + 0x98EDF1023ACE71DEULL) + aOASaltB[((aIndex + 330U)) & S_SALT1];
            aOrbiterB = (aWandererK + RotL64(aPrevious, 27U)) + 0x42861D318BF192C1ULL;
