            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0x74BDC70E1D169CB3ULL) + aOUSaltH[(((511U - aIndex) + 344U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x4CDFBF5CE4399D38ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x24EAC823886BBB2BULL), 29U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x0BA4268B3CFD62BEULL) + aOUSaltF[(((511U - aIndex) + 318U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0xBA133F0114214F61ULL) ^ aOUSaltC[((aIndex + 385U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xDBC925021D4A266BULL), 3U);
