            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x35D49C31FBD8EC78ULL) + aOUSaltB[(((511U - aIndex) + 151U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x278A845C3E24C776ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xAAC78506CB9BE06FULL), 43U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x39D864130FD91BA4ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterI) ^ 0x66E55FB7EAE1ACAFULL) ^ aOUSaltE[((aIndex + 319U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x97D9617CB5ADB9B7ULL), 19U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x43367C4FB9E99046ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x0EAB75B11ADD3F28ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xECFB590BBF723F6DULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x0CA8B399DE9D1E4AULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0xB54AC9CA0DC45C27ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xB50CDF2539D8ACF9ULL), 53U);
